<div class="menu-pop" id="menuPop">
  <button class="btn">New chart</button><button class="btn">Open</button>
  <button class="btn">Save</button><button class="btn">Export chart</button>
</div>
<main class="workspace">
  <div class="chart-card"><svg id="chart" viewBox="0 0 700 416" aria-label="Chart"></svg></div>
  <div class="code-pill">Try code.livegap.com <span class="new">New</span></div>
