</main>
<aside class="rail">
  <div class="brand"><img src="__PLACEHOLDER_ASSETS_BASE_DIR__/010.png" width="185" height="80" alt="Livegap Charts"></div>
  <div class="sections">
    <button class="btn section-title">Chart</button>
    <button class="btn section-title">Colors</button>
    <button class="btn section-title">inGraph Data</button>
    <button class="btn section-title">Legend</button>
