    <tbody>
      <tr><th>2023</th><td data-series="0" data-index="0">65</td><td data-series="0" data-index="1">8</td><td data-series="0" data-index="2">90</td><td data-series="0" data-index="3">81</td><td data-series="0" data-index="4">56</td><td data-series="0" data-index="5">55</td><td data-series="0" data-index="6">40</td><td class="blank"></td><td class="blank"></td></tr>
      <tr><th>2024</th><td data-series="1" data-index="0">21</td><td data-series="1" data-index="1">48</td><td data-series="1" data-index="2">40</td><td data-series="1" data-index="3">19</td><td data-series="1" data-index="4">96</td><td data-series="1" data-index="5">27</td><td data-series="1" data-index="6">99</td><td class="blank"></td><td class="blank"></td></tr>
