<script>
(() => {
  const months = ["January","February","March","April","May","June","July"];
  const values = [[65,8,90,81,56,55,40],[21,48,40,19,96,27,99]];
  const colors = [
    { line:"#399bd2", fill:"rgba(78,169,218,.43)" },
    { line:"#23d66a", fill:"rgba(45,211,133,.54)" }
  ];
  const svg = document.getElementById("chart");
  const NS = "http://www.w3.org/2000/svg";
  function el(tag, attrs={}, text="") {
    const n=document.createElementNS(NS,tag);
    Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));
    if(text) n.textContent=text;
    return n;
  }
  function smoothPath(points) {
    let d=`M ${points[0][0]} ${points[0][1]}`;
    for(let i=0;i<points.length-1;i++){
      const p0=points[Math.max(0,i-1)], p1=points[i], p2=points[i+1], p3=points[Math.min(points.length-1,i+2)];
      const c1x=p1[0]+(p2[0]-p0[0])/6, c1y=p1[1]+(p2[1]-p0[1])/6;
      const c2x=p2[0]-(p3[0]-p1[0])/6, c2y=p2[1]-(p3[1]-p1[1])/6;
      d+=` C ${c1x} ${c1y}, ${c2x} ${c2y}, ${p2[0]} ${p2[1]}`;
    }
    return d;
  }
  function drawChart(){
    svg.innerHTML="";
    svg.appendChild(el("rect",{x:0,y:0,width:700,height:416,fill:"#fff"}));
    svg.appendChild(el("text",{x:350,y:39,"text-anchor":"middle","font-size":27,fill:"#4f9ece"},"Chart Title"));
    svg.appendChild(el("text",{x:350,y:68,"text-anchor":"middle","font-size":17,fill:"#666"},"Add SubTitle Here"));
    const left=47,right=653,top=83,bottom=306;
    for(let v=0;v<=100;v+=10){
      const y=bottom-(v/100)*(bottom-top);
      svg.appendChild(el("line",{x1:left,y1:y,x2:right,y2:y,stroke:v===0?"#333":"#e4e4e4","stroke-width":v===0?1.2:1}));
      svg.appendChild(el("text",{x:39,y:y+4,"text-anchor":"end","font-size":12,fill:"#444"},String(v)));
    }
    const xs=months.map((_,i)=>left+i*(right-left)/6);
    xs.forEach((x,i)=>{
      svg.appendChild(el("line",{x1:x,y1:top,x2:x,y2:bottom,stroke:"#e7e7e7","stroke-width":1}));
      svg.appendChild(el("text",{x,y:328,"text-anchor":"middle","font-size":13,fill:"#222"},months[i]));
    });
    // Draw 2023 first so that the green series sits visibly above it.
    [0,1].forEach(series=>{
      const pts=values[series].map((v,i)=>[xs[i],bottom-(Math.max(0,Math.min(100,v))/100)*(bottom-top)]);
      const curve=smoothPath(pts);
      const area=curve+` L ${right} ${bottom} L ${left} ${bottom} Z`;
      svg.appendChild(el("path",{d:area,fill:colors[series].fill,stroke:"none"}));
      svg.appendChild(el("path",{d:curve,fill:"none",stroke:colors[series].line,"stroke-width":2.5}));
      pts.forEach((p,i)=>{
        svg.appendChild(el("text",{x:p[0],y:p[1]-7,"text-anchor":"middle","font-size":12,"font-style":"italic",fill:"#333"},String(values[series][i])));
      });
    });
    // legend
    svg.appendChild(el("rect",{x:288,y:363,width:16,height:16,fill:"rgba(45,211,133,.3)",stroke:"#25d76a","stroke-width":2}));
    svg.appendChild(el("text",{x:309,y:376,"font-size":16,fill:"#333"},"2024"));
    svg.appendChild(el("rect",{x:352,y:363,width:16,height:16,fill:"rgba(78,169,218,.3)",stroke:"#399bd2","stroke-width":2}));
    svg.appendChild(el("text",{x:373,y:376,"font-size":16,fill:"#333"},"2023"));
    svg.appendChild(el("text",{x:350,y:400,"text-anchor":"middle","font-size":13,fill:"#555"},"Made with Livegap Charts"));
  }
  drawChart();
  document.querySelectorAll("td[data-series]").forEach(cell=>{
    cell.addEventListener("click",()=>{
      if(cell.querySelector("input")) return;
      document.querySelectorAll("td.selected").forEach(x=>x.classList.remove("selected"));
      cell.classList.add("selected");
      const input=document.createElement("input");
      input.value=cell.textContent.trim();
      cell.textContent="";
      cell.appendChild(input);
      input.focus(); input.select();
      const finish=()=>{
        const s=Number(cell.dataset.series), i=Number(cell.dataset.index);
        const raw=input.value.trim();
        const num=Number(raw);
        if(raw!=="" && Number.isFinite(num)) values[s][i]=num;
        cell.textContent=raw || String(values[s][i]);
        cell.classList.remove("selected");
        drawChart();
      };
      input.addEventListener("blur",finish,{once:true});
      input.addEventListener("keydown",e=>{ if(e.key==="Enter"){e.preventDefault();input.blur();} if(e.key==="Escape"){input.value=String(values[Number(cell.dataset.series)][Number(cell.dataset.index)]);input.blur();} });
    });
  });
  document.getElementById("pointHeader").addEventListener("click",()=>{
    const panel=document.getElementById("pointPanel");
    panel.classList.toggle("open");
    document.getElementById("pointHeader").classList.toggle("active");
  });
  document.querySelectorAll(".section-title:not(#pointHeader)").forEach(button=>{
    button.addEventListener("click",()=>{
      document.querySelectorAll(".section-title").forEach(b=>{if(b!==button)b.classList.remove("active");});
      button.classList.toggle("active");
    });
  });
  document.querySelectorAll(".menu-btn").forEach(btn=>btn.addEventListener("click",()=>{
    const pop=document.getElementById("menuPop");
    pop.style.display=pop.style.display==="block"?"none":"block";
    pop.style.left=Math.max(0,btn.offsetLeft)+"px";
  }));
  document.querySelector(".data-tab").addEventListener("click",()=>{
    document.querySelector(".table-wrap").classList.toggle("collapsed");
    const t=document.querySelector(".table-wrap");
    t.style.height=t.classList.contains("collapsed")?"34px":"var(--table)";
  });
  document.querySelector(".floating").addEventListener("click",()=>{});
})();
</script>
</body>
</html>
